#define _POSIX_C_SOURCE 200809L
#include "crashpad/store.h"
#include "crashpad/pager.h"
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>

#define CP_WAL_MAGIC 0x4c575043u
#define CP_WAL_PREP 1u
#define CP_WAL_COMMIT 2u
#define CP_NODE_KEYS 31u
#define CP_WAL_MAX_TX 4096u
#define CP_SNAPSHOT_BASE (8u * 1024u * 1024u)
#define CP_SNAPSHOT_MAGIC 0x4e535043u
typedef struct cp_node { int leaf;uint16_t n;uint64_t key[CP_NODE_KEYS+1],val[CP_NODE_KEYS+1];struct cp_node*child[CP_NODE_KEYS+2],*next; } cp_node;
struct cp_store {cp_blockdev*dev;size_t cap,used,hand;cp_node*root;pthread_mutex_t mu;uint64_t next_tx,snapshot_tx;atomic_uint_fast64_t ops;int owns_dev,needs_recovery;};
static cp_node*node_new(int leaf){cp_node*n=calloc(1,sizeof(*n));if(n)n->leaf=leaf;return n;}
static void tree_free(cp_node*n){if(!n)return;if(!n->leaf)for(uint16_t i=0;i<=n->n;i++)tree_free(n->child[i]);free(n);}
static int insert_rec(cp_node*n,uint64_t k,uint64_t v,uint64_t*up,cp_node**right){*right=NULL;if(!n)return 0;if(n->leaf){uint16_t i=0;while(i<n->n&&n->key[i]<k)i++;if(i<n->n&&n->key[i]==k){n->val[i]=v;return 1;}if(n->n<CP_NODE_KEYS){memmove(&n->key[i+1],&n->key[i],(size_t)(n->n-i)*sizeof(uint64_t));memmove(&n->val[i+1],&n->val[i],(size_t)(n->n-i)*sizeof(uint64_t));n->key[i]=k;n->val[i]=v;n->n++;return 1;}uint64_t keys[CP_NODE_KEYS+1],vals[CP_NODE_KEYS+1];memcpy(keys,n->key,i*sizeof(uint64_t));memcpy(vals,n->val,i*sizeof(uint64_t));keys[i]=k;vals[i]=v;memcpy(keys+i+1,n->key+i,(CP_NODE_KEYS-i)*sizeof(uint64_t));memcpy(vals+i+1,n->val+i,(CP_NODE_KEYS-i)*sizeof(uint64_t));cp_node*r=node_new(1);if(!r)return 0;n->n=16;r->n=16;memcpy(n->key,keys,16*sizeof(uint64_t));memcpy(n->val,vals,16*sizeof(uint64_t));memcpy(r->key,keys+16,16*sizeof(uint64_t));memcpy(r->val,vals+16,16*sizeof(uint64_t));r->next=n->next;n->next=r;*up=r->key[0];*right=r;return 1;}
 uint16_t i=0;while(i<n->n&&k>=n->key[i])i++;uint64_t sep=0;cp_node*r=NULL;if(!insert_rec(n->child[i],k,v,&sep,&r))return 0;if(!r)return 1;if(n->n<CP_NODE_KEYS){memmove(&n->key[i+1],&n->key[i],(size_t)(n->n-i)*sizeof(uint64_t));memmove(&n->child[i+2],&n->child[i+1],(size_t)(n->n-i)*sizeof(cp_node*));n->key[i]=sep;n->child[i+1]=r;n->n++;return 1;}uint64_t keys[CP_NODE_KEYS+1];cp_node*children[CP_NODE_KEYS+3];memcpy(keys,n->key,i*sizeof(uint64_t));keys[i]=sep;memcpy(keys+i+1,n->key+i,(CP_NODE_KEYS-i)*sizeof(uint64_t));memcpy(children,n->child,(i+1)*sizeof(cp_node*));children[i+1]=r;memcpy(children+i+2,n->child+i+1,(CP_NODE_KEYS-i)*sizeof(cp_node*));cp_node*nr=node_new(0);if(!nr)return 0;*up=keys[16];n->n=16;nr->n=15;memcpy(n->key,keys,16*sizeof(uint64_t));memcpy(n->child,children,17*sizeof(cp_node*));memcpy(nr->key,keys+17,15*sizeof(uint64_t));memcpy(nr->child,children+17,16*sizeof(cp_node*));*right=nr;return 1;}
static int tree_put(cp_store*s,uint64_t k,uint64_t v){if(!s->root){s->root=node_new(1);if(!s->root)return 0;s->root->key[0]=k;s->root->val[0]=v;s->root->n=1;return 1;}uint64_t up=0;cp_node*r=NULL;if(!insert_rec(s->root,k,v,&up,&r))return 0;if(r){cp_node*root=node_new(0);if(!root){tree_free(r);return 0;}root->key[0]=up;root->child[0]=s->root;root->child[1]=r;root->n=1;s->root=root;}return 1;}
static cp_node*tree_clone_rec(const cp_node*src,cp_node**last){if(!src)return NULL;cp_node*n=node_new(src->leaf);if(!n)return NULL;n->n=src->n;memcpy(n->key,src->key,sizeof(src->key));memcpy(n->val,src->val,sizeof(src->val));if(src->leaf){if(*last)(*last)->next=n;*last=n;return n;}for(uint16_t i=0;i<=src->n;i++){n->child[i]=tree_clone_rec(src->child[i],last);if(!n->child[i]){tree_free(n);return NULL;}}return n;}
static cp_node*tree_clone(const cp_node*root){cp_node*last=NULL;return tree_clone_rec(root,&last);}
static cp_node*find_leaf(cp_node*n,uint64_t k){while(n&&!n->leaf){uint16_t i=0;while(i<n->n&&k>=n->key[i])i++;n=n->child[i];}return n;}
static uint32_t crc(const void*p,size_t n){return cp_crc32c(p,n,0);}
static void put32(uint8_t*p,uint32_t v){for(int i=0;i<4;i++)p[i]=(uint8_t)(v>>(8*i));}
static void put64(uint8_t*p,uint64_t v){for(int i=0;i<8;i++)p[i]=(uint8_t)(v>>(8*i));}
static uint32_t get32(const uint8_t*p){uint32_t v=0;for(int i=3;i>=0;i--)v=(v<<8)|p[i];return v;}
static uint64_t get64(const uint8_t*p){uint64_t v=0;for(int i=7;i>=0;i--)v=(v<<8)|p[i];return v;}
static cp_status log_record(cp_store*s,uint32_t type,uint64_t tx,uint64_t key,uint64_t val){if(tx>=CP_WAL_MAX_TX)return CP_E_RANGE;uint8_t b[CP_SECTOR_SIZE]={0};put32(b,CP_WAL_MAGIC);put32(b+4,type);put64(b+8,tx);put64(b+16,key);put64(b+24,val);put32(b+32,crc(b,32));uint64_t off=CP_PAGE_SIZE+(tx*2+(type==CP_WAL_COMMIT))*CP_SECTOR_SIZE;return cp_dev_write(s->dev,off,b,sizeof b);}
static cp_status load_snapshot(cp_store*s){cp_page meta;if(cp_page_read(s->dev,0,&meta)!=CP_OK)return CP_E_CORRUPT;const void*raw=NULL;uint16_t len=0;if(cp_page_chdr(&meta)->type!=CP_PAGE_META||cp_page_get_cell(&meta,0,&raw,&len)!=CP_OK||len!=40)return CP_E_CORRUPT;const uint8_t*m=raw;if(get32(m)!=CP_SNAPSHOT_MAGIC||get32(m+4)!=1||get32(m+28)!=0)return CP_E_CORRUPT;uint64_t tx=get64(m+8),rows=get64(m+32);uint32_t pages=get32(m+24);if(get64(m+16)!=(pages?CP_SNAPSHOT_BASE/CP_PAGE_SIZE:0))return CP_E_CORRUPT;if(tx>CP_WAL_MAX_TX||cp_page_chdr(&meta)->lsn!=tx||cp_page_chdr(&meta)->aux!=(pages?CP_SNAPSHOT_BASE/CP_PAGE_SIZE:0)||rows>tx||(pages==0&&rows!=0)||(pages!=0&&(rows<pages||rows>(uint64_t)pages*CP_NODE_KEYS)))return CP_E_CORRUPT;uint64_t device_size=0;if(cp_dev_size(s->dev,&device_size)!=CP_OK||device_size<CP_SNAPSHOT_BASE||(uint64_t)pages>(device_size-CP_SNAPSHOT_BASE)/CP_PAGE_SIZE)return CP_E_CORRUPT;cp_store rebuilt={0};atomic_init(&rebuilt.ops,0);uint64_t seen=0,last_key=0;int have_key=0;for(uint32_t i=0;i<pages;i++){uint64_t id=CP_SNAPSHOT_BASE/CP_PAGE_SIZE+i;cp_page p;if(cp_page_read(s->dev,id,&p)!=CP_OK||cp_page_chdr(&p)->type!=CP_PAGE_BTREE_LEAF||cp_page_chdr(&p)->lsn!=tx||cp_page_chdr(&p)->aux!=(i+1<pages?id+1:0)){tree_free(rebuilt.root);return CP_E_CORRUPT;}const cp_page_header*h=cp_page_chdr(&p);for(uint16_t j=0;j<h->nslots;j++){const void*cell=NULL;uint16_t n=0;if(cp_page_get_cell(&p,j,&cell,&n)!=CP_OK||n!=16){tree_free(rebuilt.root);return CP_E_CORRUPT;}const uint8_t*b=cell;uint64_t key=get64(b),value=get64(b+8);if(have_key&&key<=last_key){tree_free(rebuilt.root);return CP_E_CORRUPT;}if(!tree_put(&rebuilt,key,value)){tree_free(rebuilt.root);return CP_E_NOMEM;}last_key=key;have_key=1;seen++;}}if(seen!=rows){tree_free(rebuilt.root);return CP_E_CORRUPT;}s->root=rebuilt.root;s->next_tx=tx;s->snapshot_tx=tx;atomic_store(&s->ops,tx);return CP_OK;}
static cp_status replay(cp_store*s){uint64_t size=0;cp_status r=cp_dev_size(s->dev,&size);if(r!=CP_OK)return r;uint64_t slots=size>CP_PAGE_SIZE?(size-CP_PAGE_SIZE)/CP_SECTOR_SIZE:0;uint64_t expected_tx=s->next_tx;for(uint64_t tx=expected_tx;tx<CP_WAL_MAX_TX&&tx*2+1<slots;tx++){uint8_t a[CP_SECTOR_SIZE],b[CP_SECTOR_SIZE];uint64_t off=CP_PAGE_SIZE+tx*2*CP_SECTOR_SIZE;if(cp_dev_read(s->dev,off,a,sizeof a)!=CP_OK)break;if(get32(a)!=CP_WAL_MAGIC||get32(a+4)!=CP_WAL_PREP||get32(a+32)!=crc(a,32))break;if(cp_dev_read(s->dev,off+CP_SECTOR_SIZE,b,sizeof b)!=CP_OK)break;if(get32(b)!=CP_WAL_MAGIC||get32(b+4)!=CP_WAL_COMMIT||get32(b+32)!=crc(b,32)||get64(b+8)!=tx||get64(b+16)!=get64(a+16)||get64(b+24)!=get64(a+24))break;if(!tree_put(s,get64(a+16),get64(a+24)))return CP_E_NOMEM;s->ops++;expected_tx++;}s->next_tx=expected_tx;return CP_OK;}
static cp_status store_flush_wal(void*ctx,uint64_t lsn){cp_store*s=ctx;if(!s||lsn>s->next_tx)return CP_E_RANGE;return cp_dev_sync(s->dev);}
cp_status cp_store_open(cp_blockdev*d,size_t buffers,cp_store**out){if(!d||!out)return CP_E_RANGE;cp_store*s=calloc(1,sizeof(*s));if(!s)return CP_E_NOMEM;s->dev=d;s->cap=buffers?buffers:64;s->next_tx=0;atomic_init(&s->ops,0);if(pthread_mutex_init(&s->mu,NULL)){free(s);return CP_E_IO;}cp_status snap=load_snapshot(s);if(snap==CP_E_NOMEM){cp_store_close(s);return snap;}cp_status r=replay(s);if(r!=CP_OK){cp_store_close(s);return r;}*out=s;return CP_OK;}
void cp_store_close(cp_store*s){if(!s)return;tree_free(s->root);pthread_mutex_destroy(&s->mu);if(s->owns_dev)cp_dev_close(s->dev);free(s);}
cp_status cp_store_put(cp_store*s,uint64_t k,uint64_t v){if(!s)return CP_E_RANGE;pthread_mutex_lock(&s->mu);if(s->needs_recovery){pthread_mutex_unlock(&s->mu);return CP_E_IO;}cp_store staged={0};staged.root=tree_clone(s->root);if(s->root&&!staged.root){pthread_mutex_unlock(&s->mu);return CP_E_NOMEM;}if(!tree_put(&staged,k,v)){tree_free(staged.root);pthread_mutex_unlock(&s->mu);return CP_E_NOMEM;}uint64_t tx=s->next_tx;cp_status r=log_record(s,CP_WAL_PREP,tx,k,v);if(r==CP_OK)r=log_record(s,CP_WAL_COMMIT,tx,k,v);if(r==CP_OK)r=cp_dev_sync(s->dev);if(r==CP_OK){cp_node*old=s->root;s->root=staged.root;staged.root=NULL;tree_free(old);s->next_tx++;s->ops++;}else s->needs_recovery=1;tree_free(staged.root);pthread_mutex_unlock(&s->mu);return r;}
cp_status cp_store_get(cp_store*s,uint64_t k,uint64_t*out){if(!s||!out)return CP_E_RANGE;pthread_mutex_lock(&s->mu);cp_node*n=find_leaf(s->root,k);cp_status r=CP_E_RANGE;if(n)for(uint16_t i=0;i<n->n;i++)if(n->key[i]==k){*out=n->val[i];r=CP_OK;break;}pthread_mutex_unlock(&s->mu);return r;}
static int scan_node(cp_node*n,uint64_t a,uint64_t b,cp_scan_fn cb,void*c){if(!n)return 1;if(n->leaf){for(uint16_t i=0;i<n->n;i++)if(n->key[i]>=a&&n->key[i]<=b&&!cb(n->key[i],n->val[i],c))return 0;return 1;}for(uint16_t i=0;i<=n->n;i++)if(!scan_node(n->child[i],a,b,cb,c))return 0;return 1;}
cp_status cp_store_scan(cp_store*s,uint64_t a,uint64_t b,cp_scan_fn cb,void*c){if(!s||!cb)return CP_E_RANGE;if(a>b)return CP_OK;pthread_mutex_lock(&s->mu);int ok=scan_node(s->root,a,b,cb,c);pthread_mutex_unlock(&s->mu);return ok?CP_OK:CP_E_IO;}
static cp_node*leftmost_leaf(cp_node*n){while(n&&!n->leaf)n=n->child[0];return n;}
cp_status cp_store_checkpoint(cp_store*s){if(!s)return CP_E_RANGE;pthread_mutex_lock(&s->mu);size_t pages=0;uint64_t rows=0;for(cp_node*n=leftmost_leaf(s->root);n;n=n->next){pages++;rows+=n->n;}if(pages>UINT32_MAX){pthread_mutex_unlock(&s->mu);return CP_E_RANGE;}cp_buffer_pool*pool=NULL;cp_status r=cp_buffer_pool_create(s->dev,s->cap,store_flush_wal,s,&pool);if(r!=CP_OK){pthread_mutex_unlock(&s->mu);return r;}uint64_t first=pages?CP_SNAPSHOT_BASE/CP_PAGE_SIZE:0;size_t pi=0;for(cp_node*n=leftmost_leaf(s->root);n&&r==CP_OK;n=n->next,pi++){cp_page*p=NULL;uint64_t id=first+pi;r=cp_buffer_pool_new(pool,id,CP_PAGE_BTREE_LEAF,&p);if(r!=CP_OK)break;cp_page_header*h=cp_page_hdr(p);h->lsn=s->next_tx;h->aux=pi+1<pages?id+1:0;for(uint16_t j=0;j<n->n;j++){uint8_t cell[16];put64(cell,n->key[j]);put64(cell+8,n->val[j]);r=cp_page_insert_cell(p,j,cell,sizeof cell);if(r!=CP_OK)break;}if(r==CP_OK)r=cp_buffer_pool_unpin(pool,id);}if(r==CP_OK)r=cp_buffer_pool_flush(pool);if(r==CP_OK){cp_status close_status=cp_buffer_pool_close(pool);pool=NULL;if(close_status!=CP_OK)r=close_status;}if(pool)cp_buffer_pool_destroy(pool);if(r==CP_OK){cp_page meta;cp_page_init(&meta,0,CP_PAGE_META);cp_page_header*h=cp_page_hdr(&meta);h->lsn=s->next_tx;h->aux=first;uint8_t cell[40]={0};put32(cell,CP_SNAPSHOT_MAGIC);put32(cell+4,1);put64(cell+8,s->next_tx);put64(cell+16,first);put32(cell+24,(uint32_t)pages);put64(cell+32,rows);r=cp_page_insert_cell(&meta,0,cell,sizeof cell);if(r==CP_OK)r=cp_page_write(s->dev,0,&meta);if(r==CP_OK)r=cp_dev_sync(s->dev);}if(r==CP_OK)s->snapshot_tx=s->next_tx;pthread_mutex_unlock(&s->mu);return r;}
cp_status cp_store_recover(cp_store*s){if(!s)return CP_E_RANGE;pthread_mutex_lock(&s->mu);cp_store rebuilt={0};atomic_init(&rebuilt.ops,0);rebuilt.dev=s->dev;cp_status snap=load_snapshot(&rebuilt);cp_status r=(snap==CP_OK||snap==CP_E_CORRUPT)?replay(&rebuilt):snap;if(r==CP_OK){cp_node*old=s->root;s->root=rebuilt.root;rebuilt.root=NULL;s->ops=atomic_load(&rebuilt.ops);s->next_tx=rebuilt.next_tx;s->snapshot_tx=rebuilt.snapshot_tx;s->needs_recovery=0;tree_free(old);}tree_free(rebuilt.root);pthread_mutex_unlock(&s->mu);return r;}
uint64_t cp_store_operation_count(const cp_store*s){return s?atomic_load(&s->ops):0;}
cp_blockdev*cp_store_device(cp_store*s){return s?s->dev:NULL;}
